TEMPLATE_HTML = '<title>Painel OEA JWM</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Barlow:wght@400;500;600&display=swap">\n<style>\n/* Layout: faixa de marca no topo, bloco vermelho de destaque (conclusão geral) ao lado de 8 indicadores,\n   depois módulos, ranking de setores, mapa de calor e lista de colaboradores com filtros. */\n:root{\n  --bg:#FAF6F6; --surface:#FFFFFF; --surface-2:#F6EFEF; --ink:#1E1416; --muted:#6F6164; --line:#ECE2E3;\n  --red:#D6141D; --red-deep:#9C0B12; --red-soft:#FCE8E9; --track:#EFE6E7; --on-red:#FFFFFF;\n  --good:#1B7F52; --good-bg:#E3F4EB; --warn:#9A6200; --warn-bg:#FFF1D6; --bad:#B3121A; --bad-bg:#FCE3E4;\n  --shadow:0 1px 2px rgba(60,20,24,.05),0 8px 24px -12px rgba(60,20,24,.14);\n  --f-display:\'Barlow Condensed\',\'Arial Narrow\',Arial,sans-serif;\n  --f-body:\'Barlow\',system-ui,-apple-system,\'Segoe UI\',Arial,sans-serif;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){\n  --bg:#130E0F; --surface:#1D1517; --surface-2:#251B1D; --ink:#F6EEEE; --muted:#AA9B9E; --line:#33282A;\n  --red:#FF5058; --red-deep:#C3141C; --red-soft:#3A1A1D; --track:#33282A; --on-red:#1A0B0D;\n  --good:#5AD19A; --good-bg:#16322A; --warn:#F2B64B; --warn-bg:#3A2D12; --bad:#FF8087; --bad-bg:#3C1A1D;\n  --shadow:0 1px 2px rgba(0,0,0,.4),0 10px 28px -14px rgba(0,0,0,.6); color-scheme:dark}}\n:root[data-theme="dark"]{\n  --bg:#130E0F; --surface:#1D1517; --surface-2:#251B1D; --ink:#F6EEEE; --muted:#AA9B9E; --line:#33282A;\n  --red:#FF5058; --red-deep:#C3141C; --red-soft:#3A1A1D; --track:#33282A; --on-red:#1A0B0D;\n  --good:#5AD19A; --good-bg:#16322A; --warn:#F2B64B; --warn-bg:#3A2D12; --bad:#FF8087; --bad-bg:#3C1A1D;\n  --shadow:0 1px 2px rgba(0,0,0,.4),0 10px 28px -14px rgba(0,0,0,.6); color-scheme:dark}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nbody{background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:14px;line-height:1.45;padding-inline:clamp(16px,3vw,40px);padding-block:0 40px}\n.wrap{max-width:1320px;margin-inline:auto}\nbutton,select,input{font:inherit;color:inherit}\n.num{font-variant-numeric:tabular-nums}\n.disp{font-family:var(--f-display);letter-spacing:.01em}\n.eyebrow{font-size:11.5px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}\n\n/* topo */\n.top{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding-block:20px 18px}\n.logo{background:#fff;border-radius:14px;padding:6px 12px;box-shadow:var(--shadow);border:1px solid var(--line);display:flex}\n.logo img{height:46px;width:auto;display:block}\n.ttl{flex:1 1 260px;min-width:0}\n.ttl h1{font-family:var(--f-display);font-weight:700;font-size:clamp(26px,3.6vw,38px);line-height:1;margin:0;text-wrap:balance}\n.ttl h1 em{font-style:normal;color:var(--red)}\n.ttl p{margin:6px 0 0;color:var(--muted)}\n.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.btn{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:9px 16px;cursor:pointer;font-weight:600;display:inline-flex;gap:8px;align-items:center;transition:transform .15s,border-color .15s,background .15s}\n.btn:hover{border-color:var(--red);transform:translateY(-1px)}\n.btn.primary{background:var(--red);color:var(--on-red);border-color:var(--red)}\n.btn.primary:hover{background:var(--red-deep);color:#fff;border-color:var(--red-deep)}\n.btn:focus-visible,select:focus-visible,input:focus-visible,.row:focus-visible,th button:focus-visible{outline:2px solid var(--red);outline-offset:2px}\n.btn.ic{padding:9px 11px}\n.rule{height:3px;background:linear-gradient(90deg,var(--red) 0 22%,var(--line) 22% 100%);border-radius:3px;margin-bottom:18px}\n\n/* filtros */\n.filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:18px}\n.filters label{font-size:12px;color:var(--muted);font-weight:600;letter-spacing:.06em;text-transform:uppercase}\nselect,.search{border:1px solid var(--line);background:var(--surface);border-radius:10px;padding:9px 12px;min-width:0}\nselect{max-width:100%}\n.chip-on{display:inline-flex;gap:8px;align-items:center;background:var(--red-soft);color:var(--red);border-radius:999px;padding:6px 8px 6px 14px;font-weight:600}\n.chip-on button{border:0;background:var(--red);color:var(--on-red);width:20px;height:20px;border-radius:50%;cursor:pointer;line-height:1;font-size:13px}\n\n/* grid */\n.grid{display:grid;gap:16px;grid-template-columns:repeat(12,minmax(0,1fr));margin-bottom:16px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:18px 20px;box-shadow:var(--shadow);min-width:0}\n.card h2{font-family:var(--f-display);font-weight:600;font-size:20px;margin:0 0 2px;letter-spacing:.01em}\n.card .sub{color:var(--muted);font-size:12.5px;margin:0 0 14px}\n.c4{grid-column:span 4}.c3{grid-column:span 3}.c8{grid-column:span 8}.c12{grid-column:span 12}.c6{grid-column:span 6}.c5{grid-column:span 5}.c7{grid-column:span 7}\n\n/* destaque vermelho */\n.hero{grid-column:span 4;border-radius:20px;padding:24px;color:#fff;background:radial-gradient(120% 90% at 0% 0%,#E8232B 0%,var(--red-deep) 70%);box-shadow:0 18px 40px -18px rgba(156,11,18,.6);display:flex;flex-direction:column;gap:16px;min-width:0;position:relative;overflow:hidden}\n.hero::after{content:"";position:absolute;right:-60px;bottom:-60px;width:220px;height:220px;border-radius:50%;border:34px solid rgba(255,255,255,.07)}\n.hero .eyebrow{color:rgba(255,255,255,.8)}\n.ringbox{display:flex;align-items:center;gap:20px;flex-wrap:wrap}\n.ring{position:relative;width:168px;height:168px;flex:none}\n.ring svg{width:100%;height:100%;transform:rotate(-90deg)}\n.ring .big{position:absolute;inset:0;display:grid;place-items:center;text-align:center}\n.ring .big b{font-family:var(--f-display);font-size:40px;font-weight:700;line-height:1}\n.ring .big span{display:block;font-size:11px;letter-spacing:.1em;text-transform:uppercase;opacity:.8;margin-top:2px}\n.hero .facts{display:grid;gap:10px;min-width:0;flex:1 1 130px}\n.hero .facts div{border-left:2px solid rgba(255,255,255,.45);padding-left:10px}\n.hero .facts b{font-family:var(--f-display);font-size:26px;font-weight:600;display:block;line-height:1.05}\n.hero .facts span{font-size:12px;opacity:.85}\n.hero .msg{background:rgba(255,255,255,.14);border-radius:12px;padding:10px 12px;font-size:13px;position:relative;z-index:1}\n\n.kpis{grid-column:span 8;display:grid;gap:16px;grid-template-columns:repeat(4,minmax(0,1fr))}\n.kpi{padding:16px 16px 14px;display:flex;flex-direction:column;gap:4px}\n.kpi .v{font-family:var(--f-display);font-weight:700;font-size:40px;line-height:1.05}\n.kpi .s{font-size:12.5px;color:var(--muted)}\n.kpi.alert .v{color:var(--red)}\n.kpi .mini{height:5px;background:var(--track);border-radius:3px;overflow:hidden;margin-top:6px}\n.kpi .mini i{display:block;height:100%;background:var(--red);border-radius:3px;transition:width .9s cubic-bezier(.2,.7,.2,1)}\n\n/* modulos */\n.mod{display:flex;gap:16px;align-items:center;flex-wrap:wrap}\n.donut{position:relative;width:104px;height:104px;flex:none}\n.donut svg{width:100%;height:100%;transform:rotate(-90deg)}\n.donut b{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--f-display);font-size:26px;font-weight:700}\n.mod dl{margin:0;display:grid;gap:8px;flex:1 1 90px;min-width:0}\n.mod dl div{display:flex;justify-content:space-between;gap:8px;align-items:baseline;border-bottom:1px dashed var(--line);padding-bottom:5px}\n.mod dt{color:var(--muted);font-size:12.5px;display:flex;gap:6px;align-items:center}\n.mod dd{margin:0;font-weight:600}\n.dot{width:9px;height:9px;border-radius:50%;display:inline-block;background:var(--red)}\n.dot.g{background:var(--track);box-shadow:inset 0 0 0 1px var(--muted)}\n.mname{font-size:12.5px;color:var(--muted);margin:0 0 12px;min-height:34px}\n\n/* ranking de setores */\n.rank{display:grid;gap:3px;max-height:640px;overflow:auto;padding-right:4px}\n.row{display:grid;grid-template-columns:minmax(120px,210px) 1fr 58px;gap:12px;align-items:center;padding:5px 8px;border-radius:9px;cursor:pointer;border:1px solid transparent;background:none;text-align:left;width:100%}\n.row:hover{background:var(--surface-2)}\n.row.sel{background:var(--red-soft);border-color:var(--red)}\n.row .nm{font-size:12.5px;font-weight:500;line-height:1.2;min-width:0;overflow-wrap:anywhere}\n.row .nm small{display:block;color:var(--muted);font-size:11px;font-weight:400}\n.row .tr{position:relative;height:12px;background:var(--track);border-radius:7px}\n.row .tr i{position:absolute;left:0;top:0;bottom:0;border-radius:7px;background:var(--red);width:0;transition:width .9s cubic-bezier(.2,.7,.2,1)}\n.row .tr u{position:absolute;top:-4px;bottom:-4px;width:0;border-left:2px dashed var(--ink);opacity:.55}\n.row .pv{text-align:right;font-weight:600}\n.legend{display:flex;gap:16px;flex-wrap:wrap;color:var(--muted);font-size:12px;margin-bottom:10px}\n.legend span{display:inline-flex;gap:6px;align-items:center}\n.legend .ln{width:0;height:12px;border-left:2px dashed var(--ink);opacity:.55}\n\n/* distribuicao */\n.dist{display:flex;gap:10px;align-items:flex-end;height:170px}\n.dist .col{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:6px;min-width:0}\n.dist .bar{width:100%;max-width:62px;border-radius:6px 6px 0 0;min-height:3px;transition:height .9s cubic-bezier(.2,.7,.2,1);height:0}\n.dist .col b{font-family:var(--f-display);font-size:22px;line-height:1}\n.dist .col span{font-size:11.5px;color:var(--muted);text-align:center;line-height:1.15;min-height:28px}\n\n/* gargalos */\n.bott{display:grid;gap:9px}\n.bott .b{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 10px;align-items:center;font-size:12.5px;cursor:pointer;background:none;border:0;text-align:left;width:100%;padding:0}\n.bott .b span:first-child{overflow-wrap:anywhere}\n.bott .b .t{grid-column:1/-1;height:7px;background:var(--track);border-radius:4px;overflow:hidden}\n.bott .b .t i{display:block;height:100%;background:var(--red);border-radius:4px;transition:width .9s cubic-bezier(.2,.7,.2,1);width:0}\n\n/* comparativo */\n.vs{display:grid;gap:14px}\n.vs .g{display:grid;gap:6px}\n.vs .g .h{display:flex;justify-content:space-between;gap:8px;align-items:baseline}\n.vs .g .h b{font-family:var(--f-display);font-size:30px;line-height:1}\n.vs .tr{height:10px;background:var(--track);border-radius:6px;overflow:hidden}\n.vs .tr i{display:block;height:100%;background:var(--red);border-radius:6px;transition:width .9s cubic-bezier(.2,.7,.2,1);width:0}\n.vs small{color:var(--muted)}\n\n/* mapa de calor */\n.hm{overflow-x:auto}\n.hmt{display:grid;grid-template-columns:minmax(170px,1.6fr) repeat(4,minmax(78px,1fr));gap:3px;min-width:560px;align-items:stretch}\n.hmt .hh{font-size:11px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;padding:4px 6px;text-align:center;line-height:1.2}\n.hmt .rl{font-size:12.5px;padding:6px 6px 6px 0;font-weight:500;overflow-wrap:anywhere;display:flex;align-items:center}\n.hmt .cell{border-radius:6px;display:grid;place-items:center;font-weight:600;font-size:12.5px;padding:6px 2px;transition:transform .15s}\n.hmt .cell:hover{transform:scale(1.06);position:relative;z-index:2;box-shadow:var(--shadow)}\n.hm-leg{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px;margin-top:12px}\n.hm-leg i{width:140px;height:8px;border-radius:5px;background:linear-gradient(90deg,var(--surface-2),var(--red));border:1px solid var(--line)}\n\n/* tabela */\n.tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:12px}\n.tools .search{flex:1 1 220px}\n.seg{display:flex;gap:6px;flex-wrap:wrap}\n.seg button{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:6px 12px;cursor:pointer;font-weight:500;font-size:12.5px}\n.seg button[aria-pressed="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}\n.seg button .n{opacity:.65;margin-left:4px}\n.tw{overflow-x:auto;border:1px solid var(--line);border-radius:12px}\ntable{border-collapse:collapse;width:100%;min-width:860px}\nth{font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);text-align:left;padding:0;background:var(--surface-2);position:sticky;top:0}\nth button{all:unset;cursor:pointer;display:block;padding:10px 12px;width:100%;box-sizing:border-box;font-weight:600}\nth button:hover{color:var(--red)}\ntd{padding:9px 12px;border-top:1px solid var(--line);vertical-align:middle}\ntbody tr:hover{background:var(--surface-2)}\n.pn b{display:block;font-weight:600}\n.pn small{color:var(--muted);font-size:11.5px;display:block;max-width:320px;overflow-wrap:anywhere}\n.mc{display:flex;align-items:center;gap:6px;min-width:70px}\n.mc .tr{flex:1;height:6px;background:var(--track);border-radius:4px;overflow:hidden;min-width:28px}\n.mc .tr i{display:block;height:100%;background:var(--red)}\n.mc span{font-size:12px;width:34px;text-align:right}\n.pill{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:3px 10px;font-size:12px;font-weight:600;white-space:nowrap}\n.pill.ok{background:var(--good-bg);color:var(--good)}\n.pill.mid{background:var(--warn-bg);color:var(--warn)}\n.pill.no{background:var(--bad-bg);color:var(--bad)}\n.tag{font-size:10.5px;font-weight:600;background:var(--surface-2);color:var(--muted);border-radius:6px;padding:1px 6px;margin-left:6px;letter-spacing:.04em;text-transform:uppercase;border:1px solid var(--line)}\n.foot{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:12px;margin-top:22px}\n.more{display:flex;justify-content:center;margin-top:12px}\n.empty{padding:28px;text-align:center;color:var(--muted)}\n#toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translate(-50%,20px);background:var(--ink);color:var(--bg);padding:10px 18px;border-radius:999px;opacity:0;transition:.25s;pointer-events:none;z-index:50;font-weight:500;max-width:90vw}\n#toast.on{opacity:1;transform:translate(-50%,0)}\n.drop{position:fixed;inset:0;background:rgba(214,20,29,.9);color:#fff;display:grid;place-items:center;font-family:var(--f-display);font-size:34px;z-index:60}\n\n@media (max-width:1100px){.hero,.kpis{grid-column:span 12}.c4{grid-column:span 6}.c8,.c7,.c5{grid-column:span 12}.c3{grid-column:span 6}}\n@media (max-width:760px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.c4,.c3,.c6{grid-column:span 12}.row{grid-template-columns:minmax(0,1fr) 52px;}.row .tr{grid-column:1/-1;order:3}.kpi .v{font-size:34px}.ring{width:140px;height:140px}.ring .big b{font-size:34px}}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n</style>\n\n<div class="wrap">\n  <header class="top">\n    <div class="logo"><img alt="JWM Soluções Logísticas" src="__LOGO__"></div>\n    <div class="ttl">\n      <h1>Treinamentos <em>OEA</em></h1>\n      <p id="periodo" class="num">Operador Econômico Autorizado · acompanhamento por setor</p>\n    </div>\n    <div class="actions">\n      <input type="file" id="file" accept=".xlsx,.xls" hidden>\n      <button class="btn primary" id="btnUp" type="button" title="Carregue uma planilha nova para atualizar o painel neste navegador">\n        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 16V4M7 9l5-5 5 5M4 20h16"/></svg>\n        Atualizar planilha</button>\n      <button class="btn ic" id="btnTheme" type="button" aria-label="Alternar tema claro e escuro">\n        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4.5"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.4 1.4M17.6 17.6L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/></svg>\n      </button>\n    </div>\n  </header>\n  <div class="rule"></div>\n\n  <div class="filters" id="filters">\n    <label for="selSetor">Setor</label>\n    <select id="selSetor"></select>\n    <span id="chipOn"></span>\n  </div>\n\n  <section class="grid" id="top">\n    <div class="hero" id="hero"></div>\n    <div class="kpis" id="kpis"></div>\n  </section>\n\n  <section class="grid" id="mods"></section>\n\n  <section class="grid">\n    <div class="card c7">\n      <h2>Realização por setor</h2>\n      <p class="sub">Média de conclusão dos 3 módulos. Clique em um setor para filtrar o painel.</p>\n      <div class="legend"><span><i class="dot"></i> média do setor</span><span><i class="ln"></i> média geral da empresa</span></div>\n      <div class="rank" id="rank"></div>\n    </div>\n    <div style="grid-column:span 5;display:grid;gap:16px;align-content:start;min-width:0">\n      <div class="card">\n        <h2>Como as pessoas estão distribuídas</h2>\n        <p class="sub" id="distSub">Colaboradores por faixa de conclusão</p>\n        <div class="dist" id="dist"></div>\n      </div>\n      <div class="card">\n        <h2>Onde estão as pendências</h2>\n        <p class="sub">Setores com mais pessoas ainda sem finalizar. Clique para filtrar.</p>\n        <div class="bott" id="bott"></div>\n      </div>\n    </div>\n  </section>\n\n  <section class="grid">\n    <div class="card c12">\n      <h2>Mapa de calor: setor × módulo</h2>\n      <p class="sub">Quanto mais vermelho, maior a realização. Mostra em qual módulo cada setor está travado.</p>\n      <div class="hm"><div class="hmt" id="hm"></div></div>\n      <div class="hm-leg"><span>0%</span><i></i><span>100%</span></div>\n    </div>\n  </section>\n\n  <section class="grid">\n    <div class="card c12">\n      <h2>Colaboradores</h2>\n      <p class="sub" id="tblSub"></p>\n      <div class="tools">\n        <input class="search" id="q" type="search" placeholder="Buscar por nome, e-mail ou cargo" aria-label="Buscar colaborador">\n        <div class="seg" id="seg"></div>\n        <button class="btn" id="btnCopy" type="button">Copiar e-mails da lista</button>\n      </div>\n      <div class="tw"><table>\n        <thead><tr id="thead"></tr></thead>\n        <tbody id="tbody"></tbody>\n      </table></div>\n      <div class="more"><button class="btn" id="btnMore" type="button" hidden>Mostrar mais</button></div>\n    </div>\n  </section>\n\n  <div class="foot"><span id="src"></span><span>JWM Transportes Soluções Logísticas Ltda</span></div>\n</div>\n<div id="toast" role="status"></div>\n<div class="drop" id="drop" hidden>Solte a planilha para atualizar</div>\n\n<script src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js"></script>\n<script>\nconst INIT = __DATA__;\nconst MODS = [\'Conceitos e Diretrizes OEA\',\'Gerenciamento de Riscos\',\'Segurança para a Cadeia Logística\'];\nconst MSHORT = [\'Conceitos\',\'Riscos\',\'Segurança\'];\nconst $ = s => document.querySelector(s);\nconst fmtP = (x,d=1) => (x*100).toFixed(d).replace(\'.\',\',\')+\'%\';\nconst fmtN = n => n.toLocaleString(\'pt-BR\');\nconst esc = s => String(s??\'\').replace(/[&<>"]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\'}[c]));\n\nlet DATA=null, ROWS=[], S={setor:\'\',status:\'all\',q:\'\',sort:\'pct\',dir:1,limit:25};\n\n/* ---------- leitura e regras ---------- */\nfunction modPct(t){\n  if(typeof t===\'number\') return t>1?t/100:t;\n  t=String(t??\'\').trim(); if(!t) return 0;\n  const m=t.match(/\\(([\\d.,]+)\\s*%\\)/);\n  if(m) return parseFloat(m[1].replace(\'.\',\'\').replace(\',\',\'.\'))/100 || 0;\n  return /^(conclu|sim|realizado)/i.test(t)?1:0;\n}\nconst modDone = t => /^conclu/i.test(String(t??\'\').trim());\nfunction title(n){\n  const small=[\'de\',\'da\',\'do\',\'das\',\'dos\',\'e\'];\n  return String(n||\'\').trim().toLowerCase().split(/\\s+/).map((w,i)=>i&&small.includes(w)?w:w.charAt(0).toUpperCase()+w.slice(1)).join(\' \');\n}\nfunction buildRows(raw){\n  return raw.filter(r=>r[0]).map(r=>{\n    const k=String(r[7]||\'\').trim().toUpperCase();\n    const p=[modPct(r[2]),modPct(r[3]),modPct(r[4])];\n    const d=[modDone(r[2]),modDone(r[3]),modDone(r[4])];\n    const pct = k===\'OK\' ? 1 : (p[0]+p[1]+p[2])/3;\n    const afast = /DESLIG/.test(k)?\'Desligado\':/F[ÉE]RIAS/.test(k)?\'Férias\':/LICEN/.test(k)?\'Licença\':\'\';\n    return {nome:title(r[0]),email:String(r[1]||\'\').trim().toLowerCase(),p,d,\n      setor:String(r[5]||\'\').trim()||\'SEM SETOR\',cargo:String(r[6]||\'\').trim(),pct,afast,\n      st: pct>=0.9999?\'ok\':pct<=0?\'no\':\'mid\'};\n  });\n}\nfunction parseWorkbook(buf,name){\n  const wb=XLSX.read(buf,{type:\'array\'});\n  let ws=null;\n  for(const n of wb.SheetNames){ if(n.trim().toUpperCase()===\'COLABORADORES\'){ws=wb.Sheets[n];break;} }\n  if(!ws) for(const n of wb.SheetNames){ const a=XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1,raw:true}); if(a.slice(0,10).some(r=>r.some(c=>String(c).trim().toLowerCase()===\'aluno\'))){ws=wb.Sheets[n];break;} }\n  if(!ws) throw new Error(\'Não encontrei a aba COLABORADORES com a coluna Aluno.\');\n  const a=XLSX.utils.sheet_to_json(ws,{header:1,raw:true,defval:null});\n  const hi=a.findIndex(r=>r.some(c=>String(c).trim().toLowerCase()===\'aluno\'));\n  const h=a[hi].map(c=>String(c??\'\').trim().toLowerCase());\n  const col=(f)=>h.findIndex(f);\n  const idx={nome:col(x=>x===\'aluno\'),email:col(x=>x===\'e-mail\'||x===\'email\'),\n    m:[0,1,2].map(i=>col(x=>x.startsWith(\'módulo\')||x.startsWith(\'modulo\'))),setor:col(x=>x===\'setor\'),cargo:col(x=>x===\'cargo\'),fin:col(x=>x===\'finalizado\')};\n  const mi=h.map((x,i)=>(x.startsWith(\'módulo\')||x.startsWith(\'modulo\'))?i:-1).filter(i=>i>=0);\n  const raw=[];\n  for(let i=hi+1;i<a.length;i++){\n    const r=a[i]; if(!r||!r[idx.nome]) continue;\n    raw.push([r[idx.nome],r[idx.email],r[mi[0]],r[mi[1]],r[mi[2]],r[idx.setor],r[idx.cargo],r[idx.fin]]);\n  }\n  let periodo=\'\'; for(let i=0;i<hi;i++) for(const c of a[i]) if(typeof c===\'string\'&&/data de in/i.test(c)) periodo=c;\n  return {raw,periodo,fonte:name,gerado:new Date().toLocaleDateString(\'pt-BR\')};\n}\nfunction parseEnd(p){const m=String(p).match(/t[eé]rmino:\\s*(\\d{2})\\/(\\d{2})\\/(\\d{4})/i);return m?new Date(+m[3],+m[2]-1,+m[1]):null}\nfunction parseStart(p){const m=String(p).match(/in[ií]cio:\\s*(\\d{2})\\/(\\d{2})\\/(\\d{4})/i);return m?new Date(+m[3],+m[2]-1,+m[1]):null}\nfunction businessDays(from,to){let n=0;const d=new Date(from.getFullYear(),from.getMonth(),from.getDate());while(d<=to){const w=d.getDay();if(w&&w<6)n++;d.setDate(d.getDate()+1)}return n}\n\n/* ---------- agregações ---------- */\nconst avg = a => a.length?a.reduce((s,x)=>s+x,0)/a.length:0;\nfunction bySetor(rows){\n  const m=new Map();\n  rows.forEach(r=>{if(!m.has(r.setor))m.set(r.setor,[]);m.get(r.setor).push(r)});\n  return [...m].map(([setor,l])=>({setor,n:l.length,avg:avg(l.map(r=>r.pct)),\n    mods:[0,1,2].map(i=>avg(l.map(r=>r.p[i]))),pend:l.filter(r=>r.st!==\'ok\'&&r.afast!==\'Desligado\').length,ok:l.filter(r=>r.st===\'ok\').length}));\n}\nfunction filtered(){return S.setor?ROWS.filter(r=>r.setor===S.setor):ROWS}\n\n/* ---------- animação de números ---------- */\nfunction countUp(el,to,fmt){\n  const reduce=matchMedia(\'(prefers-reduced-motion: reduce)\').matches;\n  if(reduce){el.textContent=fmt(to);return}\n  const t0=performance.now(),d=700;\n  const step=t=>{const k=Math.min(1,(t-t0)/d),e=1-Math.pow(1-k,3);el.textContent=fmt(to*e);if(k<1)requestAnimationFrame(step);else el.textContent=fmt(to)};\n  requestAnimationFrame(step);\n}\nfunction grow(){requestAnimationFrame(()=>requestAnimationFrame(()=>{document.querySelectorAll(\'[data-w]\').forEach(e=>e.style.width=e.dataset.w);document.querySelectorAll(\'[data-h]\').forEach(e=>e.style.height=e.dataset.h);document.querySelectorAll(\'[data-dash]\').forEach(e=>e.setAttribute(\'stroke-dasharray\',e.dataset.dash))}))}\n\n/* ---------- renderização ---------- */\nfunction render(){\n  const rows=filtered(), all=ROWS, total=rows.length;\n  const per=DATA.periodo||\'\'; const end=parseEnd(per), start=parseStart(per);\n  $(\'#periodo\').textContent=(per||\'Operador Econômico Autorizado\')+\'\';\n  const mean=avg(rows.map(r=>r.pct)), meanAll=avg(all.map(r=>r.pct));\n  const ok=rows.filter(r=>r.st===\'ok\').length;\n  const no=rows.filter(r=>r.st===\'no\').length;\n  const mid=total-ok-no;\n  const desl=rows.filter(r=>r.afast===\'Desligado\').length;\n  const afast=rows.filter(r=>r.afast&&r.afast!==\'Desligado\').length;\n  const pend=rows.filter(r=>r.st!==\'ok\'&&r.afast!==\'Desligado\').length;\n  const today=new Date(); today.setHours(0,0,0,0);\n  let dias=null,uteis=null,status=\'\';\n  if(end){dias=Math.round((end-today)/864e5);uteis=dias>=0?businessDays(today,end):0;}\n  const ritmo=uteis?Math.ceil(pend/uteis):null;\n  const sets=bySetor(all).filter(s=>s.n>0);\n  const full=sets.filter(s=>s.avg>=0.9999).length;\n\n  let msg;\n  if(S.setor) msg=`Filtrado: <b>${esc(S.setor)}</b> · média geral da empresa ${fmtP(meanAll)}`;\n  else if(dias===null) msg=\'Acompanhe a evolução e cobre os setores com menor realização.\';\n  else if(dias<0) msg=\'Prazo encerrado. Resultado final do período.\';\n  else msg=pend? `Faltam <b>${fmtN(pend)}</b> pessoas para 100%. Em ${uteis} dias úteis, isso exige cerca de <b>${ritmo}</b> conclusões por dia.`:\'Todos os colaboradores finalizaram os módulos.\';\n  const circ=2*Math.PI*70;\n  $(\'#hero\').innerHTML=`\n    <div class="eyebrow">Conclusão geral${S.setor?\' do setor\':\'\'}</div>\n    <div class="ringbox">\n      <div class="ring"><svg viewBox="0 0 168 168" aria-hidden="true"><circle cx="84" cy="84" r="70" fill="none" stroke="rgba(255,255,255,.22)" stroke-width="14"/><circle cx="84" cy="84" r="70" fill="none" stroke="#fff" stroke-width="14" stroke-linecap="round" stroke-dasharray="0 ${circ}" data-dash="${circ*mean} ${circ}" style="transition:stroke-dasharray 1.1s cubic-bezier(.2,.7,.2,1)"/></svg>\n        <div class="big"><div><b class="num" id="heroV">0%</b><span>média geral</span></div></div></div>\n      <div class="facts">\n        <div><b class="num">${fmtN(ok)}</b><span>finalizaram 100%</span></div>\n        <div><b class="num">${fmtN(total-ok)}</b><span>ainda em aberto</span></div>\n      </div>\n    </div>\n    <div class="msg">${msg}</div>`;\n  countUp($(\'#heroV\'),mean,fmtP);\n\n  const pctOf=n=>total?fmtP(n/total,0):\'0%\';\n  const K=[\n    {l:\'Colaboradores\',v:total,s:S.setor?`de ${fmtN(all.length)} na empresa`:\'na base de treinamento\'},\n    {l:\'Finalizaram\',v:ok,s:`${pctOf(ok)} da base`,bar:total?ok/total:0},\n    {l:\'Em andamento\',v:mid,s:`${pctOf(mid)} da base`,bar:total?mid/total:0},\n    {l:\'Não iniciaram\',v:no,s:`${pctOf(no)} da base`,bar:total?no/total:0,alert:no>0},\n    {l:\'Dias restantes\',v:dias===null?null:Math.max(dias,0),s:end?(dias<0?\'prazo encerrado\':`até ${end.toLocaleDateString(\'pt-BR\')}`):\'prazo não informado\',alert:dias!==null&&dias>=0&&dias<=7},\n    {l:\'Ritmo necessário\',v:ritmo,s:ritmo===null?\'sem prazo ativo\':\'conclusões por dia útil\'},\n    {l:\'Setores a 100%\',v:full,s:`de ${sets.length} setores`},\n    {l:\'Desligados e afastados\',v:desl+afast,s:`${desl} desligados · ${afast} afastados`},\n  ];\n  $(\'#kpis\').innerHTML=K.map((k,i)=>`<div class="card kpi ${k.alert?\'alert\':\'\'}"><span class="eyebrow">${k.l}</span><span class="v num" id="kv${i}">${k.v===null?\'–\':\'0\'}</span><span class="s">${k.s}</span>${k.bar!==undefined?`<div class="mini"><i data-w="${(k.bar*100).toFixed(1)}%" style="width:0"></i></div>`:\'\'}</div>`).join(\'\');\n  K.forEach((k,i)=>{if(k.v!==null)countUp($(\'#kv\'+i),k.v,x=>fmtN(Math.round(x)))});\n\n  /* módulos */\n  const mc=2*Math.PI*42;\n  const mhtml=[0,1,2].map(i=>{\n    const d=rows.filter(r=>r.d[i]).length, f=total?d/total:0;\n    return `<div class="card c3"><div class="eyebrow">Módulo ${i+1}</div><h2>${MSHORT[i]}</h2><p class="mname">${MODS[i]}</p>\n      <div class="mod"><div class="donut"><svg viewBox="0 0 104 104" aria-hidden="true"><circle cx="52" cy="52" r="42" fill="none" stroke="var(--track)" stroke-width="12"/><circle cx="52" cy="52" r="42" fill="none" stroke="var(--red)" stroke-width="12" stroke-linecap="round" stroke-dasharray="0 ${mc}" data-dash="${mc*f} ${mc}" style="transition:stroke-dasharray 1s cubic-bezier(.2,.7,.2,1)"/></svg><b class="num">${fmtP(f,0)}</b></div>\n      <dl><div><dt><i class="dot"></i>Concluídos</dt><dd class="num">${fmtN(d)}</dd></div><div><dt><i class="dot g"></i>Pendentes</dt><dd class="num">${fmtN(total-d)}</dd></div><div><dt>Total</dt><dd class="num">${fmtN(total)}</dd></div></dl></div></div>`}).join(\'\');\n  const mot=all.filter(r=>/MOTORISTA/.test(r.setor)), dem=all.filter(r=>!/MOTORISTA/.test(r.setor));\n  const vs=(l,a)=>`<div class="g"><div class="h"><span>${l} <small class="num">· ${fmtN(a.length)} pessoas</small></span><b class="num">${fmtP(avg(a.map(r=>r.pct)),0)}</b></div><div class="tr"><i data-w="${avg(a.map(r=>r.pct))*100}%"></i></div><small class="num">${fmtN(a.filter(r=>r.st===\'ok\').length)} finalizaram</small></div>`;\n  $(\'#mods\').innerHTML=mhtml+`<div class="card c3"><div class="eyebrow">Comparativo</div><h2>Motoristas × demais</h2><p class="mname">Média de realização dos módulos na empresa inteira</p><div class="vs">${mot.length?vs(\'Motoristas\',mot):\'\'}${dem.length?vs(\'Demais setores\',dem):\'\'}</div></div>`;\n\n  /* ranking */\n  const ord=[...sets].sort((a,b)=>b.avg-a.avg||b.n-a.n);\n  $(\'#rank\').innerHTML=ord.map(s=>`<button type="button" class="row ${S.setor===s.setor?\'sel\':\'\'}" data-set="${esc(s.setor)}" aria-pressed="${S.setor===s.setor}"><span class="nm">${esc(s.setor)}<small class="num">${s.n} ${s.n===1?\'pessoa\':\'pessoas\'} · ${s.ok} finalizaram</small></span><span class="tr"><i data-w="${s.avg*100}%"></i><u style="left:${meanAll*100}%"></u></span><span class="pv num">${fmtP(s.avg,0)}</span></button>`).join(\'\');\n\n  /* distribuição */\n  const B=[[\'Não iniciaram\',r=>r.pct<=0,\'var(--track)\'],[\'1% a 49%\',r=>r.pct>0&&r.pct<.5,\'color-mix(in srgb,var(--red) 35%,var(--surface))\'],[\'50% a 99%\',r=>r.pct>=.5&&r.pct<.9999,\'color-mix(in srgb,var(--red) 68%,var(--surface))\'],[\'100%\',r=>r.pct>=.9999,\'var(--red)\']];\n  const cnt=B.map(b=>rows.filter(b[1]).length), mx=Math.max(1,...cnt);\n  $(\'#distSub\').textContent=S.setor?`Colaboradores de ${S.setor} por faixa de conclusão`:\'Colaboradores por faixa de conclusão\';\n  $(\'#dist\').innerHTML=B.map((b,i)=>`<div class="col"><b class="num">${cnt[i]}</b><div class="bar" style="background:${b[2]};${i===0?\'box-shadow:inset 0 0 0 1px var(--muted)\':\'\'}" data-h="${Math.max(2,cnt[i]/mx*112)}px"></div><span>${b[0]}</span></div>`).join(\'\');\n\n  /* gargalos */\n  const gb=[...sets].filter(s=>s.pend>0).sort((a,b)=>b.pend-a.pend).slice(0,6), gm=Math.max(1,...gb.map(s=>s.pend));\n  $(\'#bott\').innerHTML=gb.map(s=>`<button type="button" class="b" data-set="${esc(s.setor)}"><span>${esc(s.setor)}</span><span class="num"><b>${s.pend}</b> de ${s.n}</span><span class="t"><i data-w="${s.pend/gm*100}%"></i></span></button>`).join(\'\')||\'<div class="empty">Sem pendências.</div>\';\n\n  /* heatmap */\n  const hh=[\'Setor\',...MSHORT,\'Geral\'];\n  const cellc=v=>`background:color-mix(in srgb,var(--red) ${Math.round(v*88)}%,var(--surface-2));color:${v>.62?\'var(--on-red)\':\'var(--ink)\'}`;\n  $(\'#hm\').innerHTML=hh.map((h,i)=>`<div class="hh" style="${i?\'\':\'text-align:left\'}">${h}</div>`).join(\'\')+ord.map(s=>`<div class="rl">${esc(s.setor)}</div>`+[...s.mods,s.avg].map((v,i)=>`<div class="cell num" style="${cellc(v)}" title="${esc(s.setor)} · ${hh[i+1]}: ${fmtP(v)}">${fmtP(v,0)}</div>`).join(\'\')).join(\'\');\n\n  grow(); renderTable();\n}\n\nconst COLS=[[\'nome\',\'Colaborador\'],[\'setor\',\'Setor\'],[\'m0\',\'Conceitos\'],[\'m1\',\'Riscos\'],[\'m2\',\'Segurança\'],[\'pct\',\'Total\'],[\'st\',\'Situação\']];\nfunction renderTable(){\n  let rows=filtered();\n  const counts={all:rows.length,no:0,mid:0,ok:0};rows.forEach(r=>counts[r.st]++);\n  const SEG=[[\'all\',\'Todos\'],[\'pend\',\'Pendentes\'],[\'no\',\'Não iniciaram\'],[\'mid\',\'Em andamento\'],[\'ok\',\'Finalizados\']];\n  counts.pend=counts.no+counts.mid;\n  $(\'#seg\').innerHTML=SEG.map(([k,l])=>`<button type="button" data-st="${k}" aria-pressed="${S.status===k}">${l}<span class="n num">${counts[k]}</span></button>`).join(\'\');\n  if(S.status===\'pend\') rows=rows.filter(r=>r.st!==\'ok\'); else if(S.status!==\'all\') rows=rows.filter(r=>r.st===S.status);\n  const q=S.q.trim().toLowerCase();\n  if(q) rows=rows.filter(r=>(r.nome+\' \'+r.email+\' \'+r.cargo+\' \'+r.setor).toLowerCase().includes(q));\n  const key=r=>S.sort===\'pct\'?r.pct:S.sort===\'nome\'?r.nome:S.sort===\'setor\'?r.setor:S.sort===\'st\'?r.pct:S.sort[0]===\'m\'?r.p[+S.sort[1]]:r.pct;\n  rows=[...rows].sort((a,b)=>{const x=key(a),y=key(b);const c=typeof x===\'string\'?x.localeCompare(y,\'pt-BR\'):x-y;return (c||a.nome.localeCompare(b.nome,\'pt-BR\'))*S.dir});\n  FLIST=rows;\n  $(\'#tblSub\').textContent=`${fmtN(rows.length)} ${rows.length===1?\'colaborador\':\'colaboradores\'} na lista${S.setor?\' · setor \'+S.setor:\'\'}`;\n  $(\'#thead\').innerHTML=COLS.map(([k,l])=>`<th aria-sort="${S.sort===k?(S.dir>0?\'ascending\':\'descending\'):\'none\'}"><button type="button" data-sort="${k}">${l}${S.sort===k?(S.dir>0?\' ↑\':\' ↓\'):\'\'}</button></th>`).join(\'\');\n  const lab={ok:\'Finalizado\',mid:\'Em andamento\',no:\'Não iniciou\'}, ico={ok:\'✓\',mid:\'◐\',no:\'○\'};\n  $(\'#tbody\').innerHTML=rows.slice(0,S.limit).map(r=>`<tr><td class="pn"><b>${esc(r.nome)}${r.afast?`<span class="tag">${r.afast}</span>`:\'\'}</b><small>${esc(r.cargo||r.email)}</small></td><td>${esc(r.setor)}</td>${r.p.map(v=>`<td><div class="mc"><div class="tr"><i style="width:${v*100}%"></i></div><span class="num">${Math.round(v*100)}%</span></div></td>`).join(\'\')}<td class="num"><b>${Math.round(r.pct*100)}%</b></td><td><span class="pill ${r.st}">${ico[r.st]} ${lab[r.st]}</span></td></tr>`).join(\'\')||`<tr><td colspan="7" class="empty">Nenhum colaborador encontrado com esses filtros.</td></tr>`;\n  const more=$(\'#btnMore\'); more.hidden=rows.length<=S.limit; more.textContent=`Mostrar mais (${rows.length-S.limit} restantes)`;\n}\nlet FLIST=[];\n\n/* ---------- interação ---------- */\nfunction toast(t){const e=$(\'#toast\');e.textContent=t;e.classList.add(\'on\');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove(\'on\'),2600)}\nfunction setSetor(s){S.setor=s;S.limit=25;$(\'#selSetor\').value=s;$(\'#chipOn\').innerHTML=s?`<span class="chip-on">${esc(s)} <button type="button" id="clr" aria-label="Limpar filtro de setor">×</button></span>`:\'\';render()}\nfunction fillSelect(){const l=[...new Set(ROWS.map(r=>r.setor))].sort((a,b)=>a.localeCompare(b,\'pt-BR\'));$(\'#selSetor\').innerHTML=`<option value="">Todos os setores (${ROWS.length})</option>`+l.map(s=>`<option value="${esc(s)}">${esc(s)} (${ROWS.filter(r=>r.setor===s).length})</option>`).join(\'\')}\nfunction load(d){DATA=d;ROWS=buildRows(d.raw);S.setor=\'\';S.limit=25;fillSelect();$(\'#chipOn\').innerHTML=\'\';$(\'#selSetor\').value=\'\';$(\'#src\').textContent=`Fonte: ${d.fonte||\'planilha\'} · atualizado em ${d.gerado||\'–\'} · ${ROWS.length} colaboradores`;render()}\n\ndocument.addEventListener(\'click\',e=>{\n  const t=e.target.closest(\'[data-set]\'); if(t){setSetor(S.setor===t.dataset.set?\'\':t.dataset.set);if(S.setor)document.getElementById(\'top\').scrollIntoView({behavior:\'smooth\',block:\'start\'});return}\n  if(e.target.id===\'clr\'){setSetor(\'\');return}\n  const st=e.target.closest(\'[data-st]\'); if(st){S.status=st.dataset.st;S.limit=25;renderTable();return}\n  const so=e.target.closest(\'[data-sort]\'); if(so){const k=so.dataset.sort;if(S.sort===k)S.dir*=-1;else{S.sort=k;S.dir=1}renderTable();return}\n});\n$(\'#selSetor\').addEventListener(\'change\',e=>setSetor(e.target.value));\n$(\'#q\').addEventListener(\'input\',e=>{S.q=e.target.value;S.limit=25;renderTable()});\n$(\'#btnMore\').addEventListener(\'click\',()=>{S.limit+=50;renderTable()});\n$(\'#btnCopy\').addEventListener(\'click\',async()=>{\n  const list=FLIST.map(r=>r.email).filter(Boolean).join(\'; \');\n  try{await navigator.clipboard.writeText(list);toast(`${FLIST.length} e-mails copiados`)}\n  catch(_){const ta=document.createElement(\'textarea\');ta.value=list;document.body.appendChild(ta);ta.select();let ok=false;try{ok=document.execCommand(\'copy\')}catch(_){}ta.remove();toast(ok?`${FLIST.length} e-mails copiados`:\'Não foi possível copiar neste navegador\')}\n});\n$(\'#btnTheme\').addEventListener(\'click\',()=>{const r=document.documentElement;const dark=r.dataset.theme?r.dataset.theme===\'dark\':matchMedia(\'(prefers-color-scheme: dark)\').matches;r.dataset.theme=dark?\'light\':\'dark\'});\n$(\'#btnUp\').addEventListener(\'click\',()=>$(\'#file\').click());\nfunction readFile(f){\n  if(!f)return; const fr=new FileReader();\n  fr.onload=()=>{try{const d=parseWorkbook(new Uint8Array(fr.result),f.name);if(!d.raw.length)throw new Error(\'A planilha não tem colaboradores.\');load(d);toast(\'Painel atualizado com \'+f.name)}catch(err){toast(err.message||\'Não consegui ler essa planilha\')}};\n  fr.readAsArrayBuffer(f);\n}\n$(\'#file\').addEventListener(\'change\',e=>{readFile(e.target.files[0]);e.target.value=\'\'});\nlet dc=0;\naddEventListener(\'dragenter\',e=>{e.preventDefault();dc++;$(\'#drop\').hidden=false});\naddEventListener(\'dragleave\',e=>{dc=Math.max(0,dc-1);if(!dc)$(\'#drop\').hidden=true});\naddEventListener(\'dragover\',e=>e.preventDefault());\naddEventListener(\'drop\',e=>{e.preventDefault();dc=0;$(\'#drop\').hidden=true;readFile(e.dataTransfer.files[0])});\n\nload(INIT);\n</script>\n'
LOGO_BASE64 = ''


def norm(v):
    return str(v or "").strip().lower()


def module_col(v):
    return norm(v).startswith(("módulo", "modulo"))


def read_excel(upload):
    data = upload.getvalue()
    xls = pd.ExcelFile(io.BytesIO(data))
    sheet = next((s for s in xls.sheet_names if s.strip().upper() == "COLABORADORES"), None)
    if sheet is None:
        for candidate in xls.sheet_names:
            values = pd.read_excel(io.BytesIO(data), sheet_name=candidate, header=None, dtype=object).fillna("")
            if any(norm(c) == "aluno" for row in values.iloc[:10].values.tolist() for c in row):
                sheet = candidate
                break
    if sheet is None:
        raise ValueError("Não encontrei a aba COLABORADORES com a coluna Aluno.")

    values_df = pd.read_excel(io.BytesIO(data), sheet_name=sheet, header=None, dtype=object)
    values = values_df.fillna("").values.tolist()
    header = next((i for i, row in enumerate(values) if any(norm(c) == "aluno" for c in row)), None)
    if header is None:
        raise ValueError("Não encontrei a linha de cabeçalho com a coluna Aluno.")
    heads = [norm(c) for c in values[header]]
    mods = [i for i, h in enumerate(heads) if module_col(h)]
    if len(mods) < 3:
        raise ValueError("A planilha precisa ter pelo menos três colunas de módulo.")

    def col(*names):
        names = set(names)
        return next((i for i, h in enumerate(heads) if h in names), None)

    idx = {"nome": col("aluno"), "email": col("e-mail", "email"), "setor": col("setor"), "cargo": col("cargo"), "fin": col("finalizado")}
    if idx["nome"] is None:
        raise ValueError("A coluna Aluno é obrigatória.")

    raw = []
    for row in values[header + 1:]:
        if idx["nome"] >= len(row) or not row[idx["nome"]]:
            continue
        get = lambda key: row[idx[key]] if idx[key] is not None and idx[key] < len(row) else ""
        raw.append([get("nome"), get("email"), *(row[i] if i < len(row) else "" for i in mods[:3]), get("setor"), get("cargo"), get("fin")])

    periodo = ""
    for row in values[:header]:
        for value in row:
            if isinstance(value, str) and "data de in" in value.lower():
                periodo = value
    return {"raw": raw, "periodo": periodo, "fonte": upload.name, "gerado": datetime.date.today().strftime("%d/%m/%Y")}


def render(data):
    template = TEMPLATE_HTML
    logo = "data:image/png;base64," + LOGO_BASE64
    payload = json.dumps(data, ensure_ascii=False).replace("</", "<\\/")
    return template.replace("__DATA__", payload).replace("__LOGO__", logo)


def main():
    st.markdown("<style>header[data-testid='stHeader'], div[data-testid='stToolbar']{display:none} .block-container{padding:0;max-width:none}</style>", unsafe_allow_html=True)
    upload = st.file_uploader("Anexe a planilha para atualizar o dashboard", type=["xlsx", "xls"], label_visibility="collapsed")
    if upload is None:
        st.info("Anexe a planilha de colaboradores para abrir o dashboard.")
        return
    try:
        data = read_excel(upload)
        html = render(data)
    except Exception as exc:
        st.error(str(exc))
        return
    # O template original possui aproximadamente 5 mil px de conteúdo e seus próprios filtros/interações.
    components.html(html, height=5200, scrolling=True)


if __name__ == "__main__":
    main()
